Show full shader
Obviously, these are very constrained and naive examples that are largely impractical in all but the simplest scenarios. When we do any kind of 3D work, we typically need to involve things like the direction the camera’s pointing in, it’s position, it’s field of view, etc. While we could in theory hack those shaders to support these features, there is a way that’s less effort and more practical. It’s called the perspective projection matrix, and it’s the magic behind the mighty Camera.
Perspective Projection
There are a few ways to construct a perspective projection matrix, depending on your use case. Computer vision and graphics for example, have slightly different conventions for layout, which is why it’s hard to point to a single Wikipedia article and expect a universal form. That being said, in triangle-based graphics, a common convention that’s often followed involves parameterization of field of view, aspect ratio, and near and far clipping planes. These values are all very important because they also double as a way to easily know what’s in frame and what isn’t, which lets us render our scenes in performant ways, such as through culling off-screen geometry and rendering only what’s visible.
While this varies across different coordinate conventions (little consensus around which axes correspond to up, right, and forward), the general structure is mostly consistent:
\[P = \begin{bmatrix}
\frac{f}{a} & 0 & 0 & 0 \\
0 & f & 0 & 0 \\
0 & 0 & A & B \\
0 & 0 & 1 & 0
\end{bmatrix}\]
This describes a camera with focal scale \(f\) (derived from vertical fov angle \(\theta\)) and aspect ratio \(a\):
\[f = \frac{1}{\tan(\theta/2)},\quad a = \frac{width}{height}\]
Where \(A\) and \(B\) represent depth mapping, derived from near and far clipping planes \(n\) and \(F\) respectively:
\[A = \frac{F+n}{F-n}, \quad B = -\frac{2Fn}{F-n}\]
// slider:0 10
const float z = 3.5;
// slider: 20 120
const float fov = 60.0;
// slider: 0.5 2.5
const float aspect = 0.8;
// slider: 0.25 2.5
const float nearClip = 1.0;
// slider: 2.0 8.0
const float farClip = 5.0;
float f = 1.0 / tan(radians(fov) * 0.5);
mat4 p = mat4(
f / aspect, 0., 0., 0.,
0., f, 0., 0.,
0., 0., (farClip + nearClip) / (farClip - nearClip), 1.,
0., 0., -2. * farClip * nearClip / (farClip - nearClip), 0.
);
float sdSegment(vec2 p, vec2 a, vec2 b) {
vec2 pa = p - a, ba = b - a;
float h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-8), 0.0, 1.0);
return length(pa - ba * h);
}
vec2 project(mat4 m, vec3 p) {
vec4 q = m * vec4(p, 1.0);
return q.xy / q.w;
}
vec2 iso(vec3 p, float s) {
return vec2(dot(p, normalize(vec3(1., 0., 1.))),
dot(p, normalize(vec3(-.5, 1., .5)))) * s;
}
vec3 frustumPoint(vec3 c, vec3 near, vec3 far) {
vec3 s = mix(near, far, c.z);
return vec3(c.xy * s.xy, s.z);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
float t = tan(radians(fov) * 0.5);
float screenAspect = iResolution.x / iResolution.y;
float s = 1.65 / (8.0 * max(t * aspect, 1.0));
// slider:0 10
const float z = 3.5;
// slider: 20 120
const float fov = 60.0;
// slider: 0.5 2.5
const float aspect = 0.8;
// slider: 0.25 2.5
const float nearClip = 1.0;
// slider: 2.0 8.0
const float farClip = 5.0;
float f = 1.0 / tan(radians(fov) * 0.5);
mat4 p = mat4(
f / aspect, 0., 0., 0.,
0., f, 0., 0.,
0., 0., (farClip + nearClip) / (farClip - nearClip), 1.,
0., 0., -2. * farClip * nearClip / (farClip - nearClip), 0.
);
const vec3 c[8] = vec3[](
vec3(-1., -1., 0.), vec3(1., -1., 0.),
vec3(-1., 1., 0.), vec3(1., 1., 0.),
vec3(-1., -1., 1.), vec3(1., -1., 1.),
vec3(-1., 1., 1.), vec3(1., 1., 1.)
);
const ivec2 e[12] = ivec2[](
ivec2(0, 1), ivec2(0, 2), ivec2(1, 3), ivec2(2, 3),
ivec2(4, 5), ivec2(4, 6), ivec2(5, 7), ivec2(6, 7),
ivec2(0, 4), ivec2(1, 5), ivec2(2, 6), ivec2(3, 7)
);
vec3 n = vec3(nearClip * t * aspect, nearClip * t, nearClip);
vec3 F = vec3(farClip * t * aspect, farClip * t, farClip);
vec3 ball = vec3(sin(iTime), 0.0, z + cos(iTime));
const float ballRadius = 0.35;
vec4 clip = p * vec4(ball, 1.0);
vec3 q = clip.xyz / clip.w;
float visible = step(-1.0, q.z) * step(q.z, 1.0);
bool diagram = uv.x < 0.0;
vec2 lo = vec2(1e6), hi = -lo;
for (int i = 0; i < 8; i++) {
vec2 corner = iso(frustumPoint(c[i], n, F), s);
lo = min(lo, corner); hi = max(hi, corner);
}
vec2 offset = vec2(-screenAspect * 0.5, 0.0) - (lo + hi) * 0.5;
vec2 viewport = vec2(screenAspect * 0.5, 0.0);
vec2 size = 0.72 * vec2(aspect, 1.0) / max(aspect, 1.0);
float d = 0.0;
for (int i = 0; i < 12; i++) {
vec3 a = frustumPoint(c[e[i].x], n, F), b = frustumPoint(c[e[i].y], n, F);
vec2 pa = diagram ? iso(a, s) + offset : viewport + project(p, a) * size;
vec2 pb = diagram ? iso(b, s) + offset : viewport + project(p, b) * size;
float opacity = diagram ? mix(1.0, 0.4, (a.z + b.z) * 0.5 / farClip) : 0.25;
d = max(d, smoothstep(fwidth(uv.y) * 1.5, 0.0, sdSegment(uv, pa, pb)) * opacity);
}
float w = fwidth(uv.y) * 1.5;
if (diagram) {
vec2 center = iso(ball, s) + offset;
float radius = length(iso(ball + vec3(ballRadius, 0., 0.), s) - iso(ball, s));
float outline = smoothstep(w * 1.5, w, abs(length(uv - center) - radius));
d = max(d, mix(outline, smoothstep(radius + w, radius, length(uv - center)), visible));
} else {
vec2 center = viewport + q.xy * size;
float radius = length((project(p, ball + vec3(ballRadius, 0., 0.)) - q.xy) * size);
d = max(d, smoothstep(radius + w, radius, length(uv - center)) * visible);
}
d = max(d, (1.0 - smoothstep(0.0, fwidth(uv.x), abs(uv.x))) * 0.2);
